            color: #000000;
            background: #ffffff;
            padding: 0px;
            border-bottom: 1px solid #000000;
            -webkit-box-shadow: none !important;
            box-shadow: none !important;
            cursor: pointer;
            text-decoration: none;
            display: inline-block;
            border-top: none;
            border-left: none;
            border-right: none;
            transition: color 0.3s ease, background-color 0.3s ease;
