        <style id="wp-custom-css">
h2 a {
	color: #043082 !important;
}
h3 {
	margin-bottom: 12px;
}
h2 a:hover, .gun-metal-back h2 a:hover {
	color: #0693e3 !important;
}
.ht-border-bottom {
	border-bottom: 1px solid #ddd;
}
.site-header {
    background-color: rgba(2,26,71,1) !important;
}
    background: #081b46;
.site-logo, .sticky-navigation-logo {
	padding-left:30px;
}
#sticky-navigation .grid-container {
	max-width: 100%;
}
/* Sub Menu Override */
.main-navigation ul ul {
	width: auto !important;
  min-width: 200px !important;
	box-shadow: 0px 1px 4px rgb(133 139 149 / 70%) !important;
}    
.rounded-read-more {
    border-radius: 2rem;
}
.industries-served p {
	margin-bottom:0;
}
.industries-served a {
	color: #fff;
}
.industries-served .wp-block-cover .has-background-dim {
	transition: .3s;
}
.industries-served .wp-block-cover:hover .has-background-dim {
	opacity: .75;
}
.post-excerpt {
	padding-top: 2rem;
}
.inside-article p a {
	color: #0693e3;
}
.inside-article p a:hover {
	text-decoration: underline;
}
.hidden {
	display:none;
}
/* Gun-matal-gray background */
.gun-metal-back {
	  background-color: #99a1ab;
    background-image: linear-gradient(
145deg, rgba(251, 251, 252, 0.78), rgba(149, 149, 149, 0.29));
    position: relative;
    overflow: hidden;
}
.gun-metal-back:before {
	   content: "";
    background-image: url(/sites/harristhermal/wp-content/uploads/2021/11/stainless-2-scaled.jpg);
    background-repeat: no-repeat;
    background-position: top center;
    background-size: cover;
    z-index: 0;
    position: absolute;
    top: 0;
    right: 0;
    bottom: 0;
    left: 0;
    transition: inherit;
    opacity: .25;
}
.gun-metal-back h2, .gun-metal-back h2 a {
	color: #08106c !important;
}

div.gb-container.gb-container-9162873b.gun-metal-back {
	max-width: 100%;
}

/* Footer */
.site-footer p {
	margin-bottom: 0;
}
.wp-block-social-links {
	margin-bottom: 0;
